(function ($) {
	'use strict';
	const ShahiAnalyticsCharts = {
		charts: {},
		init() {
			console.log( 'ShahiLegalFlowSuite Analytics:Initializing charts...' );
			if (typeof Chart === 'undefined') {
				console.error(
					'Chart.js is not loaded. Charts cannot be rendered.'
				);
				this.showChartError();
				return;
			}
			this.initEventsChart();
			this.initHourlyChart();
			this.initUserActivityChart();
			this.initExportButton();
			console.log(
				'ShahiLegalFlowSuite Analytics:Charts initialized successfully'
			);
		},
		initEventsChart() {
			const canvas = document.getElementById( 'shahi-events-chart' );
			if ( ! canvas) {
				return;
			}
			const labels = JSON.parse(
				canvas.getAttribute( 'data-labels' ) || '[]'
			);
			const values = JSON.parse(
				canvas.getAttribute( 'data-values' ) || '[]'
			);
			const ctx = canvas.getContext( '2d' );
			this.charts.events = new Chart(
				ctx,
				{
					type: 'line',
					data: {
						labels,
						datasets: [
						{
							label: 'Events',
							data: values,
							borderColor: '#60a5fa',
							backgroundColor: 'rgba(96,165,250,0.1)',
							borderWidth: 3,
							fill: true,
							tension: 0.4,
							pointRadius: 4,
							pointBackgroundColor: '#60a5fa',
							pointBorderColor: '#ffffff',
							pointBorderWidth: 2,
							pointHoverRadius: 6,
							pointHoverBackgroundColor: '#60a5fa',
							pointHoverBorderColor: '#ffffff',
							pointHoverBorderWidth: 3,
						},
						],
					},
					options: {
						responsive: true,
						maintainAspectRatio: false,
						plugins: {
							legend: { display: false },
							tooltip: {
								backgroundColor: 'rgba(10,14,39,0.95)',
								titleColor: '#60a5fa',
								bodyColor: '#ffffff',
								borderColor: '#60a5fa',
								borderWidth: 1,
								padding: 12,
								displayColors: false,
								callbacks: {
									label( context ) {
										return (
										'Events:' +
										context.parsed.y.toLocaleString()
									);
									},
								},
							},
						},
						scales: {
							x: {
								grid: {
									color: 'rgba(45,53,97,0.5)',
									drawBorder: false,
								},
								ticks: { color: '#a8b2d1', font: { size: 12 } },
							},
							y: {
								beginAtZero: true,
								grid: {
									color: 'rgba(45,53,97,0.5)',
									drawBorder: false,
								},
								ticks: {
									color: '#a8b2d1',
									font: { size: 12 },
									callback( value ) {
										return value.toLocaleString();
									},
								},
							},
						},
						interaction: { intersect: false, mode: 'index' },
					},
				}
			);
		},
		initHourlyChart() {
			const canvas = document.getElementById( 'shahi-hourly-chart' );
			if ( ! canvas) {
				return;
			}
			const labels = JSON.parse(
				canvas.getAttribute( 'data-labels' ) || '[]'
			);
			const values = JSON.parse(
				canvas.getAttribute( 'data-values' ) || '[]'
			);
			const ctx = canvas.getContext( '2d' );
			this.charts.hourly = new Chart(
				ctx,
				{
					type: 'bar',
					data: {
						labels,
						datasets: [
						{
							label: 'Events',
							data: values,
							backgroundColor: 'rgba(147,197,253,0.8)',
							borderColor: '#93c5fd',
							borderWidth: 2,
							borderRadius: 6,
							hoverBackgroundColor: 'rgba(147,197,253,1)',
							hoverBorderColor: '#a855f7',
						},
						],
					},
					options: {
						responsive: true,
						maintainAspectRatio: false,
						plugins: {
							legend: { display: false },
							tooltip: {
								backgroundColor: 'rgba(10,14,39,0.95)',
								titleColor: '#93c5fd',
								bodyColor: '#ffffff',
								borderColor: '#93c5fd',
								borderWidth: 1,
								padding: 12,
								displayColors: false,
								callbacks: {
									label( context ) {
										return (
										'Events:' +
										context.parsed.y.toLocaleString()
									);
									},
								},
							},
						},
						scales: {
							x: {
								grid: { display: false, drawBorder: false },
								ticks: {
									color: '#a8b2d1',
									font: { size: 11 },
									maxRotation: 45,
									minRotation: 45,
								},
							},
							y: {
								beginAtZero: true,
								grid: {
									color: 'rgba(45,53,97,0.5)',
									drawBorder: false,
								},
								ticks: {
									color: '#a8b2d1',
									font: { size: 12 },
									callback( value ) {
										return value.toLocaleString();
									},
								},
							},
						},
					},
				}
			);
		},
		initUserActivityChart() {
			const canvas = document.getElementById( 'shahi-user-activity-chart' );
			if ( ! canvas) {
				return;
			}
			const labels = JSON.parse(
				canvas.getAttribute( 'data-labels' ) || '[]'
			);
			const values = JSON.parse(
				canvas.getAttribute( 'data-values' ) || '[]'
			);
			const ctx = canvas.getContext( '2d' );
			this.charts.userActivity = new Chart(
				ctx,
				{
					type: 'doughnut',
					data: {
						labels,
						datasets: [
						{
							data: values,
							backgroundColor: [
								'rgba(96,165,250,0.8)',
								'rgba(16,185,129,0.8)',
							],
							borderColor: ['#60a5fa', '#10b981'],
							borderWidth: 3,
							hoverOffset: 10,
						},
						],
					},
					options: {
						responsive: true,
						maintainAspectRatio: false,
						plugins: {
							legend: {
								position: 'bottom',
								labels: {
									color: '#a8b2d1',
									font: { size: 13, weight: '600' },
									padding: 20,
									usePointStyle: true,
									pointStyle: 'circle',
								},
							},
							tooltip: {
								backgroundColor: 'rgba(10,14,39,0.95)',
								titleColor: '#60a5fa',
								bodyColor: '#ffffff',
								borderColor: '#60a5fa',
								borderWidth: 1,
								padding: 12,
								callbacks: {
									label( context ) {
										const label = context.label || '';
										const value = context.parsed || 0;
										const total = context.dataset.data.reduce(
											function (a, b) {
												return a + b;
											},
											0
										);
									const percentage = (
										(value / total) *
										100
									).toFixed( 1 );
									return (
										label +
										':' +
										value.toLocaleString() +
										'(' +
										percentage +
										'%)'
									);
									},
								},
							},
						},
					},
				}
			);
		},
		initExportButton() {
			const self = this;
			$( '.shahi-export-btn' ).on(
				'click',
				function (e) {
					e.preventDefault();
					const format = $( this ).data( 'format' ) || 'csv';
					self.exportData( format, $( this ) );
				}
			);
		},
		exportData( format, $button ) {
			$button.addClass( 'shahi-loading' );
			$button.prop( 'disabled', true );
			setTimeout(
				function () {
					$button.removeClass( 'shahi-loading' );
					$button.prop( 'disabled', false );
					if (typeof window.ShahiNotify !== 'undefined') {
						window.ShahiNotify.success(
							'Export feature is currently a placeholder. CSV export will be implemented in production.'
						);
					} else {
						alert(
							'Export feature is currently a placeholder. CSV export will be implemented in production.'
						);
					}
				},
				1000
			);
		},
		showChartError() {
			$( '.shahi-chart-container' ).each(
				function () {
					$( this ).html(
						'<div class="shahi-chart-error" style="text-align:center;padding:40px;color:#ff4081;">' +
						'<span class="dashicons dashicons-warning" style="font-size:48px;display:block;margin-bottom:16px;"></span>' +
						'<p style="margin:0;font-size:14px;">Chart.js library not loaded. Charts cannot be rendered.</p>' +
						'<p style="margin:8px 0 0 0;font-size:12px;color:#a8b2d1;">Please ensure Chart.js is enqueued properly.</p>' +
						'</div>'
					);
				}
			);
		},
		destroy() {
			Object.keys( this.charts ).forEach(
				function (key) {
					if (this.charts[key]) {
						this.charts[key].destroy();
					}
				}.bind( this )
			);
			this.charts = {};
		},
	};
	$( document ).ready(
		function () {
			if ($( '.shahi-analytics-page' ).length > 0) {
				ShahiAnalyticsCharts.init();
			}
		}
	);
	window.ShahiAnalyticsCharts = ShahiAnalyticsCharts;
})( jQuery );
